{
  "mechanisms": [
    {
      "name": "asymmetric_learning_rates",
      "title": "Asymmetric Learning Rates",
      "description": "Separate learning rates are used for positive and negative reward prediction errors at both stages.",
      "params": [
        {
          "name": "alpha_pos",
          "bounds": [0, 1]
        },
        {
          "name": "alpha_neg",
          "bounds": [0, 1]
        }
      ],
      "evidence": "alpha_1 = alpha_pos if delta_stage1 >= 0 else alpha_neg\nq_stage1_mf[action_1[trial]] += alpha_1 * delta_stage1\n\ndelta_stage2 = reward[trial] - q_stage2_mf[state_idx, action_2[trial]]\nalpha_2 = alpha_pos if delta_stage2 >= 0 else alpha_neg\nq_stage2_mf[state_idx, action_2[trial]] += alpha_2 * delta_stage2",
      "expressible_in_slots": true
    },
    {
      "name": "separate_mb_mf_temperatures",
      "title": "Separate MB and MF Temperatures",
      "description": "Model-based and model-free values at Stage 1 are weighted by separate inverse temperature parameters rather than a single mixing weight.",
      "params": [
        {
          "name": "beta_mb",
          "bounds": [0, 10]
        },
        {
          "name": "beta_mf",
          "bounds": [0, 10]
        }
      ],
      "evidence": "exp_q1 = np.exp(beta_mb * q_stage1_mb + beta_mf * q_stage1_mf + pers_bonus)",
      "expressible_in_slots": true
    },
    {
      "name": "eligibility_trace",
      "title": "Eligibility Trace",
      "description": "Stage 1 model-free values are updated by the Stage 2 reward prediction error scaled by an eligibility trace parameter.",
      "params": [
        {
          "name": "lam",
          "bounds": [0, 1]
        }
      ],
      "evidence": "alpha_lam = alpha_pos if delta_stage2 >= 0 else alpha_neg\nq_stage1_mf[action_1[trial]] += alpha_lam * lam * delta_stage2",
      "expressible_in_slots": true
    },
    {
      "name": "stage_1_perseveration",
      "title": "Stage 1 Perseveration",
      "description": "A perseveration bonus is added to the Stage 1 action value of the choice made on the previous trial.",
      "params": [
        {
          "name": "pers",
          "bounds": [0, 10]
        }
      ],
      "evidence": "pers_bonus = np.zeros(2)\nif last_action != -1:\n    pers_bonus[last_action] = pers\n\nexp_q1 = np.exp(beta_mb * q_stage1_mb + beta_mf * q_stage1_mf + pers_bonus)\n...\nlast_action = action_1[trial]",
      "expressible_in_slots": true
    },
    {
      "name": "stage_2_unchosen_decay",
      "title": "Stage 2 Unchosen Action Decay",
      "description": "Stage 2 model-free values for unchosen actions and unvisited states decay towards zero.",
      "params": [
        {
          "name": "decay_2",
          "bounds": [0, 1]
        }
      ],
      "evidence": "for s in range(2):\n    for a in range(2):\n        if not (s == state_idx and a == action_2[trial]):\n            q_stage2_mf[s, a] *= (1.0 - decay_2)",
      "expressible_in_slots": true
    }
  ]
}
